import re

HEAD = re.compile(r'^(?P<severity>[IWEF])(?P<date>\d{4}) (?P<time>\d{2}:\d{2}:\d{2}\.\d+)\s+(?P<pid>\d+) (?P<file>[^:\s]+):(?P<line>\d+)\] (?P<msg>.*)$')
QUOTED = re.compile(r'^"((?:[^"\\]|\\.)*)"\s*(.*)$', re.S)

def parse(lines):
    rows = []
    used = []
    for i, l in enumerate(lines):
        m = HEAD.match(l)
        if m:
            rows.append({'severity': m.group('severity'), 'date': m.group('date'), 'time': m.group('time'), 'pid': m.group('pid'), 'file': m.group('file'), 'line': m.group('line'), 'raw': m.group('msg')})
            used.append(i)
        elif rows and l.strip() and l[:1] in (' ', '\t'):
            rows[-1]['raw'] += '\n' + l.strip()
            used.append(i)
    out = []
    for r in rows:
        raw = r.pop('raw')
        q = QUOTED.match(raw)
        if q:
            r['message'] = q.group(1)
            r['attributes'] = q.group(2)
        else:
            r['message'] = raw
            r['attributes'] = ''
        out.append(r)
    blocks = []
    if out:
        blocks.append({'name': 'log_entries', 'kind': 'table', 'lines': used, 'records': out})
    return {'blocks': blocks, 'skip': []}
